parameters.text:
=Filter the following job offers strictly according to the candidate profile.

INPUT JOBS:
{{ $json["jobs"].map((job, index) => `
Job #${index + 1}
ID: ${job.id}
Title: ${job.jobTitle}
Company: ${job.companyName}
`).join('\n') }}

OUTPUT (JSON array only)

parameters.jsCode:
const llmResult = $input.first().json.text

// Parse the JSON string
let ids;
try {
    ids = JSON.parse(llmResult);
} catch (error) {
    throw new Error("Failed to parse LLM output: " + error.message);
}

return [{ ids }]
